	 * @param owner the candidate owner, with its last name, postcode and telephone already set
	 * @return the matching owner's id, or {@code null} when none exists
	 */
	Integer findPossibleDuplicateOwnerId(Owner owner) throws DataAccessException;

	/**
	 * Assigns the given owner its deterministic {@code householdId} and returns it. The identifier
	 * is derived from the owner's normalized last name and postcode, so every owner in the same
	 * household (same last name, compared case-insensitively with internal whitespace collapsed,
	 * and the same postcode) receives the same value automatically, with no explicit linking or
	 * back-filling step.
	 *
	 * @param owner the owner whose {@code householdId} is computed and set
	 * @return the household identifier assigned to the owner
	 */
	String assignHousehold(Owner owner) throws DataAccessException;

	/**
	 * Returns the number of existing owners that share the given first name and last name,
	 * compared case-insensitively. Used on create to record how many namesakes an owner already
	 * had at the moment it was created.
